SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
USE `hcispanel_kpn_tmp`;

DROP TABLE IF EXISTS `_legacy_users_stage`;
CREATE TABLE `_legacy_users_stage` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `employee_id` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) DEFAULT '',
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `email_log` varchar(255) DEFAULT NULL,
  `token` varchar(255) DEFAULT NULL,
  `img_path` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SELECT `id`,LEFT(`employee_id`,25),`name`,`email`,`email_verified_at`,COALESCE(`password`,''),`remember_token`,`created_at`,`updated_at`
FROM `_legacy_users_stage`;
DROP TABLE `_legacy_users_stage`;

SET FOREIGN_KEY_CHECKS=1;
